The user wants me to act as a blind consensus definer for the term "Covenant" in biblical symbolism, returning only a JSON object matching the schema.
{
  "primarySymbolicMeaning": "A binding agreement or solemn pact between God and humanity, symbolizing God's faithful commitment to redeem and sustain His people through promises, conditions, and signs.

content.text:
{
  "primary_meaning": "A solemn, binding agreement initiated by God with humanity (or a chosen people) that establishes a relationship of divine promise, human obligation or response, and mutual faithfulness, structured across redemptive history as successive covenants (especially Noahic, Abrahamic, Mosaic, Davidic) and fulfilled in the New Covenant through Christ's blood.",
  "primary_basis": [
    "Genesis 9:8-17 (Noahic covenant with rainbow sign)",
    "Genesis 15:7-21 and 17:1-14 (Abrahamic covenant, land, seed, circumcision)",
    "Exodus 19:5-6 and 24:3-8 (Mosaic/Sinai covenant sealed by blood)",
    "2 Samuel 7:8-16 (Davidic covenant of everlasting throne)",
    "Jeremiah 31:31-34 (promise of New Covenant written on hearts)",
    "Luke 22:20 and 1 Corinthians 11:25 (Jesus instituting New Covenant in his blood)",
    "Hebrews 8:6-13 and 9:15-22 (Christ as mediator of better covenant)"
  ],
  "alternatives": [
    {
      "meaning": "A primarily legal or suzerain-vassal treaty form modeled on ancient Near Eastern political covenants, emphasizing stipulations, blessings/curses, and ratification rituals rather than intimate relationship",
      "basis": [
        "Comparative ANE treaty studies applied to Deuteronomy and Exodus 20-24",
        "Emphasis on conditional 'if-then' language in Mosaic texts"
      ],
      "prominence": "common"
    },
    {
      "meaning": "An essentially unconditional divine promise of grace and election (especially Abrahamic/Davidic/New), with human response secondary or enabled by God, downplaying bilateral obligation",
      "basis": [
        "Genesis 15 (God alone passes between pieces)",
        "Romans 4 and Galatians 3 (covenant of promise vs law)",
        "Reformed covenant-of-grace formulations"
      ],
      "prominence": "common"
    },
    {
      "meaning": "A symbol or type of marital/familial bond between God and his people, with covenant faithfulness imaged as spousal loyalty and idolatry as adultery",
      "basis": [
        "Hosea 1-3",
        "Ezekiel 16 and 23",
        "Ephesians 5:22-33",
        "Revelation 19:7-9 (marriage supper of the Lamb)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "In dispensational readings, sharply distinct administrations or economies rather than a unified covenant of grace, with the church not directly under Israel's covenants",
      "basis": [
        "Distinctions drawn from Ephesians 3:2-6 and progressive revelation schemes",
        "Separation of Israel and church in prophetic fulfillment"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Primarily a human social or ethical compact (horizontal) that secondarily reflects divine order, rather than a vertically initiated redemptive instrument",
      "basis": [
        "Some modern ethical or liberation readings of covenant law",
        "Emphasis on mutual human agreements in tribal or communal settings"
      ],
      "prominence": "rare"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Christian tradition across Catholic, Orthodox, and Protestant streams shows broad agreement that 'covenant' denotes God's structured, promissory relationship with humanity centered on Christ as fulfillment; differences concern the exact number, conditionality, and continuity of covenants rather than the core concept itself. Scholarly ANE parallels are widely accepted as background but do not displace the theological reading. No major strand treats the term as lacking settled symbolic/theological content."
}
